775:     /// Converts from `&mut Result<T, E>` to `Result<&mut T, &mut E>`.
776:     ///
777:     /// # Examples
778:     ///
779:     /// ```
780:     /// fn mutate(r: &mut Result<i32, i32>) {
781:     ///     match r.as_mut() {
782:     ///         Ok(v) => *v = 42,
783:     ///         Err(e) => *e = 0,
784:     ///     }
785:     /// }
786:     ///
787:     /// let mut x: Result<i32, i32> = Ok(2);
788:     /// mutate(&mut x);

rust_declaration.source_text:
pub const fn as_ref(&self) -> Result<&T, &E> {
        match *self {
            Ok(ref x) => Ok(x),
            Err(ref x) => Err(x),
        }
    }
